#include <bits/stdc++.h>
using namespace std;

string removeZeroes(const string& str) {
    string result;
    for (char c : str) {
        if (c != '0') {
            result += c;
        }
    }
    return result;
}

long long convert(const string& str) {
    string filtered = removeZeroes(str);
    if (filtered.empty() || filtered == "-") {
        return 0;
    }
    return stoll(filtered);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    long long p = convert(to_string(a));
    long long q = convert(to_string(b));
    long long r = convert(to_string(a + b));

    cout << (p + q == r ? "YES\n" : "NO\n");
    return 0;
}

